  }catch(error){
    console.error(error.stack||error);
    try{writeFileSync(output+'.error.json',JSON.stringify({passed:false,error:String(error.stack||error)},null,2)+'\n');}catch{}
    clearTimeout(timer);app.exit(1);
  }
})();

