  ? plan.status !== 'bank-only-frozen' || plan.source_pending !== true || plan.no_tree_commit_branch_ref_or_ci !== true
  : !/^codex\/k12-core-202611(?:16|17)-/.test(plan.branch))) throw new Error('Wrong transport scope');
