    schemaVersion: 1, mode: 'bundled', runtimeId,
    sourcePath: path.join(destination, 'core'),
    pythonPath: path.join(basePath, python),
    nodePath: path.join(basePath, node),
    webPath: path.join(destination, 'web'), basePath, runtimeHome,
