  fs.writeFileSync(__dirname+'/NATIVE-VISIBILITY-SELFCHECK.json',JSON.stringify({passed:true,checks,network_calls:0,browser_calls:0,model_calls:0},null,2)+'\n');
})().catch(error=>{console.error(error);process.exitCode=1});

